		base::menu::as::util::RegisterGlobalFunction(engine, "void AttachEntityToEntityPhysically(int entity1, int entity2, int boneIndex1, int boneIndex2, float xPos1, float yPos1, float zPos1, float xPos2, float yPos2, float zPos2, float xRot, float yRot, float zRot, float breakForce, bool fixedRot, bool p15, bool collision, bool p17, int p18)", AngelScript::asFUNCTION(base::menu::natives::ENTITY::ATTACH_ENTITY_TO_ENTITY_PHYSICALLY), AngelScript::asCALL_CDECL)
			.Desc(R"ASDOC(breakForce is the amount of force required to break the bond.
p14 - is always 1 in scripts
p15 - is 1 or 0 in scripts - unknoun what it does
p16 - controls collision between the two entities (FALSE disables collision).
p17 - do not teleport entity to be attached to the position of the bone Index of the target entity (if 1, entity will not be teleported to target bone)
p18 - is always 2 in scripts.)ASDOC");
		base::menu::as::util::RegisterGlobalFunction(engine, "void AttachEntityToEntityPhysicallyOverrideInverseMass(int firstEntityIndex, int secondEntityIndex, int firstEntityBoneIndex, int secondEntityBoneIndex, float secondEntityOffsetX, float secondEntityOffsetY, float secondEntityOffsetZ, float firstEntityOffsetX, float firstEntityOffsetY, float firstEntityOffsetZ, float vecRotationX, float vecRotationY, float vecRotationZ, float physicalStrength, bool constrainRotation, bool doInitialWarp, bool collideWithEntity, bool addInitialSeperation, int rotOrder, float invMassScaleA, float invMassScaleB)", AngelScript::asFUNCTION(base::menu::natives::ENTITY::ATTACH_ENTITY_TO_ENTITY_PHYSICALLY_OVERRIDE_INVERSE_MASS), AngelScript::asCALL_CDECL);
