		base::menu::as::util::RegisterGlobalFunction(engine, "void SetWarningMessageWithHeader(const std::string&in entryHeader, const std::string&in entryLine1, int instructionalKey, const std::string&in entryLine2, bool p4, int p5, NativeHandle@ showBackground, NativeHandle@ p7, bool p8, int p9)", AngelScript::asFUNCTION(HudSetWarningMessageWithHeaderShim), AngelScript::asCALL_CDECL)
			.Desc(R"ASDOC(Shows a warning message on screen with a header.
Note: You can only use text entries. No custom text. You can recreate this easily with scaleforms.
Example: https://i.imgur.com/ITJt8bJ.png)ASDOC");
		base::menu::as::util::RegisterGlobalFunction(engine, "void SetWarningMessageWithHeaderAndSubstringFlags(const std::string&in entryHeader, const std::string&in entryLine1, int instructionalKey, const std::string&in entryLine2, bool p4, int p5, int additionalIntInfo, const std::string&in additionalTextInfoLine1, const std::string&in additionalTextInfoLine2, bool showBackground, int errorCode)", AngelScript::asFUNCTION(HudSetWarningMessageWithHeaderAndSubstringFlagsShim), AngelScript::asCALL_CDECL)
			.Desc(R"ASDOC(You can use this native for custom input, without having to use any scaleform-related natives.
The native must be called on tick.
The entryHeader must be a valid label.
For Single lines use JL_INVITE_N as entryLine1, JL_INVITE_ND for multiple.
Notes:
- additionalIntInfo: replaces first occurrence of ~1~ in provided label with an integer
- additionalTextInfoLine1: replaces first occurrence of ~a~ in provided label, with your custom text
- additionalTextInfoLine2: replaces second occurrence of ~a~ in provided label, with your custom text
- showBackground: shows black background of the warning screen
- errorCode: shows an error code at the bottom left if nonzero
Example of usage:
SET_WARNING_MESSAGE_WITH_HEADER_AND_SUBSTRING_FLAGS("ALERT", "JL_INVITE_ND", 66, "", true, -1, -1, "Testing line 1", "Testing line 2", true, 0);
Screenshot:
https://i.imgur.com/MsSIhPV.png)ASDOC");
		base::menu::as::util::RegisterGlobalFunction(engine, "void SetWarningMessageWithHeaderExtended(const std::string&in entryHeader, const std::string&in entryLine1, int flags, const std::string&in entryLine2, bool p4, int p5, NativeHandle@ p6, NativeHandle@ p7, bool showBg, int p9, int p10)", AngelScript::asFUNCTION(HudSetWarningMessageWithHeaderExtendedShim), AngelScript::asCALL_CDECL);
		base::menu::as::util::RegisterGlobalFunction(engine, "void SetWarningMessageWithHeaderAndSubstringFlagsExtended(const std::string&in labelTitle, const std::string&in labelMessage, int p2, int p3, const std::string&in labelMessage2, bool p5, int p6, int p7, const std::string&in p8, const std::string&in p9, bool background, int errorCode)", AngelScript::asFUNCTION(HudSetWarningMessageWithHeaderAndSubstringFlagsExtendedShim), AngelScript::asCALL_CDECL)
			.Desc(R"ASDOC(labelTitle: Label of the alert's title.
labelMsg: Label of the alert's message.
p2: This is an enum, check the description for a list.
p3: This is an enum, check the description for a list.
labelMsg2: Label of another message line
p5: usually 0
p6: usually -1
p7: usually 0
p8: unknown label
p9: unknown label
background: Set to anything other than 0 or false (even any string) and it will draw a background. Setting it to 0 or false will draw no background.
errorCode: Error code, shown at the bottom left if set to value other than 0.

instructionalKey enum list:
Buttons = {
Empty = 0,
Select = 1, -- (RETURN)
Ok = 2, -- (RETURN)
Yes = 4, -- (RETURN)
Back = 8, -- (ESC)
Cancel = 16, -- (ESC)
No = 32, -- (ESC)
RetrySpace = 64, -- (SPACE)
Restart = 128, -- (SPACE)
Skip = 256, -- (SPACE)
Quit = 512, -- (ESC)
Adjust = 1024, -- (ARROWS)
SpaceKey = 2048, -- (SPACE)
Share = 4096, -- (SPACE)
SignIn = 8192, -- (SPACE)
Continue = 16384, -- (RETURN)
AdjustLeftRight = 32768, -- (SCROLL L/R)
AdjustUpDown = 65536, -- (SCROLL U/D)
Overwrite = 131072, -- (SPACE)
SocialClubSignup = 262144, -- (RETURN)
Confirm = 524288, -- (RETURN)
Queue = 1048576, -- (RETURN)
RetryReturn = 2097152, -- (RETURN)
BackEsc = 4194304, -- (ESC)
SocialClub = 8388608, -- (RETURN)
Spectate = 16777216, -- (SPACE)
OkEsc = 33554432, -- (ESC)
CancelTransfer = 67108864, -- (ESC)
LoadingSpinner = 134217728,
NoReturnToGTA = 268435456, -- (ESC)
CancelEsc = 536870912, -- (ESC)
}

Alt = {
Empty = 0,
No = 1, -- (SPACE)
Host = 2, -- (ESC)
SearchForJob = 4, -- (RETURN)
ReturnKey = 8, -- (TURN)
Freemode = 16, -- (ESC)
})ASDOC");
