		base::menu::as::util::RegisterGlobalFunction(engine, "int NetworkGetGameRestartReason()", AngelScript::asFUNCTION(base::menu::natives::NETWORK::_NETWORK_GET_GAME_RESTART_REASON), AngelScript::asCALL_CDECL)
			.Desc(R"ASDOC(enum eNetworkGameRestartReason
{
BE_RESTART_SERVICE_NOT_RUNNING = 1, 	// BattlEye service not running
BE_RESTART_SERVICE_NEEDS_UPDATE, 		// BattlEye service needs an update
BE_RESTART_UNKNOWN_REASON,				// Unknown BattlEye reason
BE_RESTART_EF_DISABLED_WITH_BE,			// BattlEye Enforcement Flag is disabled, but BattlEye is active
BE_RESTART_EF_ENABLED_NO_BE,			// BattlEye Enforcement Flag is enabled, but BattlEye is not active
BE_RESTART_BE_MODULES_FAILED_TO_LOAD,	// BattlEye modules failed to load
NUM_NETWORK_GAME_RESTART_REASONS
};)ASDOC");
		base::menu::as::util::RegisterGlobalFunction(engine, "void NetworkConfirmGameRestart()", AngelScript::asFUNCTION(base::menu::natives::NETWORK::_NETWORK_CONFIRM_GAME_RESTART), AngelScript::asCALL_CDECL)
			.Desc(R"ASDOC(If the restart reason is 4 (BE_RESTART_EF_DISABLED_WITH_BE), will cause the game to exit with exit code 622011. Otherwise exits with code 622010. Has no effect when a restart hasn't been requested (reason == 0 or reason > 6).

Note that this 'confirmation' itself does not restart the game, a call to QUIT_GAME or similar is required afterwards.)ASDOC");
		base::menu::as::util::RegisterGlobalFunction(engine, "std::string NetworkGetGameRestartReasonMessageLabel()", AngelScript::asFUNCTION(NetworkNetworkGetGameRestartReasonMessageLabelShim), AngelScript::asCALL_CDECL)
			.Desc(R"ASDOC(Returns the restart reason as a string, see _NETWORK_GET_GAME_RESTART_REASON. Returns a null pointer when a restart hasn't been requested (reason == 0 or reason > 6).)ASDOC");
		base::menu::as::util::RegisterGlobalFunction(engine, "std::string NetworkGetBattleyeErrorMessageLabel(int errorCode)", AngelScript::asFUNCTION(NetworkNetworkGetBattleyeErrorMessageLabelShim), AngelScript::asCALL_CDECL)
			.Desc(R"ASDOC(0x20211000 = HUD_BE_ERROR_FAILED_UNKNOWN
0x20212000 = HUD_BE_ERROR_FAILED_CLIENT_INIT
0x20213000 = HUD_BE_ERROR_FAILED_SERVER_INIT
0x20214000 = HUD_BE_ERROR_FAILED_AUTH_ATTEMPTS
0x20215000 = HUD_BE_ERROR_UNTRUSTED_HOST
0x20216000 = HUD_BE_ERROR_KICKED
0x20217000 = HUD_BE_ERROR_BANNED
0x50140000 = HUD_BE_BLOCK_BANNED

Note: an invalid error code returns a null pointer!)ASDOC");

